<meta name="component" content="StrategyStatesPage">

<!-- Every strategy component in every fixture state it declares, a captioned
     cell each, in a grid that scrolls (docs/ui.md §6.1). -->
<scroll id="Page">
  <div id="Cells">
    <section class="cell" data-member="selection"><span class="caption">{$captions.selection_default}</span><div class="stage"><StrategySelection title={$selection_default.title} summary={$selection_default.summary} focused={$selection_default.focused} units={$selection_default_units} commands={$selection_default_commands} /></div></section>
    <section class="cell" data-member="selection"><span class="caption">{$captions.selection_single}</span><div class="stage"><StrategySelection title={$selection_single.title} summary={$selection_single.summary} focused={$selection_single.focused} units={$selection_single_units} commands={$selection_single_commands} /></div></section>
    <section class="cell" data-member="selection"><span class="caption">{$captions.selection_empty}</span><div class="stage"><StrategySelection title={$selection_empty.title} summary={$selection_empty.summary} focused={$selection_empty.focused} units={$selection_empty_units} commands={$selection_empty_commands} /></div></section>
    <section class="cell" data-member="selection"><span class="caption">{$captions.selection_disabled}</span><div class="stage"><StrategySelection title={$selection_disabled.title} summary={$selection_disabled.summary} focused={$selection_disabled.focused} units={$selection_disabled_units} commands={$selection_disabled_commands} /></div></section>
    <section class="cell" data-member="selection"><span class="caption">{$captions.selection_overflow}</span><div class="stage"><StrategySelection title={$selection_overflow.title} summary={$selection_overflow.summary} focused={$selection_overflow.focused} units={$selection_overflow_units} commands={$selection_overflow_commands} /></div></section>
    <section class="cell" data-member="queue"><span class="caption">{$captions.queue_default}</span><div class="stage"><StrategyQueue title={$queue_default.title} queued={$queue_default.queued} limit={$queue_default.limit} full={$queue_default.full} items={$queue_default_items} /></div></section>
    <section class="cell" data-member="queue"><span class="caption">{$captions.queue_empty}</span><div class="stage"><StrategyQueue title={$queue_empty.title} queued={$queue_empty.queued} limit={$queue_empty.limit} full={$queue_empty.full} items={$queue_empty_items} /></div></section>
    <section class="cell" data-member="queue"><span class="caption">{$captions.queue_full}</span><div class="stage"><StrategyQueue title={$queue_full.title} queued={$queue_full.queued} limit={$queue_full.limit} full={$queue_full.full} items={$queue_full_items} /></div></section>
    <section class="cell" data-member="queue"><span class="caption">{$captions.queue_paused}</span><div class="stage"><StrategyQueue title={$queue_paused.title} queued={$queue_paused.queued} limit={$queue_paused.limit} full={$queue_paused.full} items={$queue_paused_items} /></div></section>
    <section class="cell" data-member="queue"><span class="caption">{$captions.queue_overflow}</span><div class="stage"><StrategyQueue title={$queue_overflow.title} queued={$queue_overflow.queued} limit={$queue_overflow.limit} full={$queue_overflow.full} items={$queue_overflow_items} /></div></section>
    <section class="cell" data-member="wave"><span class="caption">{$captions.wave_default}</span><div class="stage"><StrategyWave wave={$wave_default.wave} waves={$wave_default.waves} phase={$wave_default.phase} next={$wave_default.next} nextTotal={$wave_default.nextTotal} finalWave={$wave_default.finalWave} canCallEarly={$wave_default.canCallEarly} reward={$wave_default.reward} enemies={$wave_default_enemies} /></div></section>
    <section class="cell" data-member="wave"><span class="caption">{$captions.wave_active}</span><div class="stage"><StrategyWave wave={$wave_active.wave} waves={$wave_active.waves} phase={$wave_active.phase} next={$wave_active.next} nextTotal={$wave_active.nextTotal} finalWave={$wave_active.finalWave} canCallEarly={$wave_active.canCallEarly} reward={$wave_active.reward} enemies={$wave_active_enemies} /></div></section>
    <section class="cell" data-member="wave"><span class="caption">{$captions.wave_final}</span><div class="stage"><StrategyWave wave={$wave_final.wave} waves={$wave_final.waves} phase={$wave_final.phase} next={$wave_final.next} nextTotal={$wave_final.nextTotal} finalWave={$wave_final.finalWave} canCallEarly={$wave_final.canCallEarly} reward={$wave_final.reward} enemies={$wave_final_enemies} /></div></section>
    <section class="cell" data-member="wave"><span class="caption">{$captions.wave_done}</span><div class="stage"><StrategyWave wave={$wave_done.wave} waves={$wave_done.waves} phase={$wave_done.phase} next={$wave_done.next} nextTotal={$wave_done.nextTotal} finalWave={$wave_done.finalWave} canCallEarly={$wave_done.canCallEarly} reward={$wave_done.reward} enemies={$wave_done_enemies} /></div></section>
    <section class="cell" data-member="wave"><span class="caption">{$captions.wave_empty}</span><div class="stage"><StrategyWave wave={$wave_empty.wave} waves={$wave_empty.waves} phase={$wave_empty.phase} next={$wave_empty.next} nextTotal={$wave_empty.nextTotal} finalWave={$wave_empty.finalWave} canCallEarly={$wave_empty.canCallEarly} reward={$wave_empty.reward} enemies={$wave_empty_enemies} /></div></section>
    <section class="cell" data-member="wave"><span class="caption">{$captions.wave_overflow}</span><div class="stage"><StrategyWave wave={$wave_overflow.wave} waves={$wave_overflow.waves} phase={$wave_overflow.phase} next={$wave_overflow.next} nextTotal={$wave_overflow.nextTotal} finalWave={$wave_overflow.finalWave} canCallEarly={$wave_overflow.canCallEarly} reward={$wave_overflow.reward} enemies={$wave_overflow_enemies} /></div></section>
    <section class="cell" data-member="tower"><span class="caption">{$captions.tower_default}</span><div class="stage"><StrategyTower name={$tower_default.name} icon={$tower_default.icon} portrait={$tower_default.portrait} level={$tower_default.level} canSell={$tower_default.canSell} sellText={$tower_default.sellText} stats={$tower_default_stats} paths={$tower_default_paths} /></div></section>
    <section class="cell" data-member="tower"><span class="caption">{$captions.tower_maxed}</span><div class="stage"><StrategyTower name={$tower_maxed.name} icon={$tower_maxed.icon} portrait={$tower_maxed.portrait} level={$tower_maxed.level} canSell={$tower_maxed.canSell} sellText={$tower_maxed.sellText} stats={$tower_maxed_stats} paths={$tower_maxed_paths} /></div></section>
    <section class="cell" data-member="tower"><span class="caption">{$captions.tower_disabled}</span><div class="stage"><StrategyTower name={$tower_disabled.name} icon={$tower_disabled.icon} portrait={$tower_disabled.portrait} level={$tower_disabled.level} canSell={$tower_disabled.canSell} sellText={$tower_disabled.sellText} stats={$tower_disabled_stats} paths={$tower_disabled_paths} /></div></section>
    <section class="cell" data-member="tower"><span class="caption">{$captions.tower_empty}</span><div class="stage"><StrategyTower name={$tower_empty.name} icon={$tower_empty.icon} portrait={$tower_empty.portrait} level={$tower_empty.level} canSell={$tower_empty.canSell} sellText={$tower_empty.sellText} stats={$tower_empty_stats} paths={$tower_empty_paths} /></div></section>
    <section class="cell" data-member="tower"><span class="caption">{$captions.tower_overflow}</span><div class="stage"><StrategyTower name={$tower_overflow.name} icon={$tower_overflow.icon} portrait={$tower_overflow.portrait} level={$tower_overflow.level} canSell={$tower_overflow.canSell} sellText={$tower_overflow.sellText} stats={$tower_overflow_stats} paths={$tower_overflow_paths} /></div></section>
  </div>
</scroll>

<style>
#Page { width: stretch; height: stretch; }
#Cells { display: grid; grid-template-columns: repeat(auto-fill, minmax(calc(var(--size-xxl) * 4.4), 1fr)); gap: var(--space-lg); padding: var(--space-lg); }
.cell { display: flex; flex-direction: column; gap: var(--space-xs); min-width: 0; }
.cell[data-member=selection] { grid-column: span 2; }
.caption { font: var(--text-caption); color: var(--ink-muted); }
.stage { display: flex; min-width: 0; align-items: flex-start; padding: var(--space-sm); border-radius: var(--radius-sm); background: var(--well); }
@media (width < 600px) {
  #Cells { grid-template-columns: minmax(0, 1fr); padding: var(--space-sm); gap: var(--space-md); }
  .cell[data-member=selection] { grid-column: span 1; }
}
</style>
